/// <summary>
/// This is a contract class
/// CB355_DutyRoll
/// </summary>
[
    DataContractAttribute
]
final class METDutyAdValorumClaimGenerateContract
{
    boolean   dutyValuesBySite;
    boolean   generateClaims;
    boolean   filterItemSite;
    container conItems;
    int       tasksNumber;
    str       physicalTableName;
    List      itemList = new List (Types::String);
    List      siteList = new List (Types::String);

}

