/// <summary>
/// Update site specific duty values parameter
/// </summary>
/// <param name = "_dutyValuesBySite">Update site specific duty values</param>
/// <returns>boolean</returns>
[
    DataMemberAttribute('dutyValuesBySite'),
    SysOperationLabelAttribute(literalstr("@MET:UpdateSiteSpecificDutyValues")),
    SysOperationHelpTextAttribute(literalStr("@MET:UpdateSiteSpecificDutyValues"))
]
public boolean parmDutyValuesBySite(boolean _dutyValuesBySite = dutyValuesBySite)
{
    dutyValuesBySite    = _dutyValuesBySite;
    return dutyValuesBySite;
}

/// <summary>
/// Generate Claims
/// </summary>
/// <param name = "_generateClaims">Generate Claims</param>
/// <returns>boolean</returns>
[
    DataMemberAttribute('generateClaims'),
    SysOperationLabelAttribute(literalstr("@MET:GenerateClaims")),
    SysOperationHelpTextAttribute(literalStr("@MET:GenerateClaims"))
]
public boolean parmGenerateClaims(boolean _generateClaims = generateClaims)
{
    generateClaims = _generateClaims;
    return generateClaims;
}

/// <summary>
