    SysOperationControlVisibilityAttribute(false)
]
public boolean parmFilterItemSite(boolean _filterItemSite = filterItemSite)
{
    filterItemSite = _filterItemSite;
    return filterItemSite;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_itemList">List of items</param>
