[
    DataMemberAttribute('Site'),
    AifCollectionTypeAttribute(identifierStr(_siteList), Types::String, extendedTypeStr(InventSiteId)),
    SysOperationLabelAttribute(literalstr("@SYS103211")),
    SysOperationHelpTextAttribute(literalStr("@SYS103211")),
    SysOperationControlVisibilityAttribute(false)
